#include <cuda_runtime.h>
#include <vector>
#include <fstream>
#include <string>
#include <chrono>
#include <cmath>
#include <filesystem>
#include <unistd.h>
#include "source_masking_kernels.inc"
#include "study_params.h"
#define C(x) do{auto e=(x);if(e!=cudaSuccess){fprintf(stderr,"CUDAfailure%s line%d\n",cudaGetErrorString(e),__LINE__);exit(1);}}while(0)
template<class A>std::vector<A>read_file(const std::string&name,int n){std::ifstream f(name,std::ios::binary);std::vector<A>a(n);f.read((char*)a.data(),n*sizeof(A));if(f.gcount()!=n*sizeof(A))exit(2);return a;}
template<class A>struct Buffer{A*base,*ptr;std::vector<A>initial;Buffer(std::vector<A>x,A guard){initial.assign(16,guard);initial.insert(initial.end(),x.begin(),x.end());initial.insert(initial.end(),16,guard);C(cudaMalloc(&base,initial.size()*sizeof(A)));ptr=base+16;reset();}void reset(){C(cudaMemcpy(base,initial.data(),initial.size()*sizeof(A),cudaMemcpyHostToDevice));}void append(std::vector<double>&out){std::vector<A>a(initial.size());C(cudaMemcpy(a.data(),base,a.size()*sizeof(A),cudaMemcpyDeviceToHost));for(A v:a)out.push_back(v);}~Buffer(){cudaFree(base);}};
struct Work{int id,n;Buffer<unsigned char>seq;Work(int k):id(k),n(NS[k]),seq(read_file<unsigned char>("case"+std::to_string(k)+"_input_u8.bin",NS[k]*33),211){}void prefix(std::vector<double>&a){a.insert(a.end(),{double(id),double(n),double((n+128)/128)});seq.append(a);}void launch(const double*mat,const unsigned char*table){maskSequences<<<(n+128)/128,128>>>(seq.ptr,mat,table,33,50,.005,.05,.9,0,0,.5,n);C(cudaGetLastError());}};
void prefix(std::vector<double>&out,Buffer<double>&mat,Buffer<unsigned char>&table,std::vector<Work*>&works){out.insert(out.end(),{33,50,.005,.05,.9,0,0,.5,128,3});mat.append(out);table.append(out);for(auto w:works)w->prefix(out);}
__global__ void observe_posterior(const unsigned char*seq,const double*mat,float*out,int*errors,int n){int gid=blockIdx.x*blockDim.x+threadIdx.x;if(gid>=n)return;float pr[33];double lookup[50],fg[50],scale[2];double growth=1/.9;double last=.005*firstRepeatOffsetProb(growth,50);double p=last;for(int j=0;j<50;j++){lookup[j]=p;p*=growth;fg[j]=0;}int err=calcRepeatProbs(pr,seq+gid*33,33,50,mat,1-.005,1-.05,.05,1/last,lookup,fg,16,scale);errors[gid]=err;for(int j=0;j<33;j++)out[gid*33+j]=pr[j];}
int main(int argc,char**argv){auto expected=read_file<double>(argv[1],COUNT);auto posterior=read_file<double>(argv[2],POSTERIOR_COUNT);std::filesystem::create_directories(argv[3]);Buffer<double>mat(read_file<double>("likelihood_f64.bin",33*33),-777);Buffer<unsigned char>table(read_file<unsigned char>("mask_table_u8.bin",33),211);std::vector<Work*>works;for(int k=0;k<3;k++)works.push_back(new Work(k));auto pipeline=[&](){for(auto w:works)w->launch(mat.ptr,table.ptr);C(cudaDeviceSynchronize());};pipeline();for(int trial=1;trial<=5;trial++){for(auto w:works)w->seq.reset();std::vector<double>out;prefix(out,mat,table,works);if(out.size()!=PREFIX)return 3;C(cudaDeviceSynchronize());auto start=std::chrono::steady_clock::now();pipeline();double seconds=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count();for(auto w:works)w->seq.append(out);bool good=out.size()==COUNT;double error=0;for(int i=0;i<COUNT;i++){double e=std::abs(out[i]-expected[i]);good=good&&std::isfinite(out[i])&&e==0;error=std::max(error,e);}std::string path=std::string(getenv("STUDY_OUTPUT_DIR"))+"/diamond_trial"+std::to_string(trial)+".bin";std::ofstream f(path,std::ios::binary);f.write((char*)out.data(),out.size()*8);f.close();printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.17g,\"correct\":%s,\"checked_values\":%zu,\"max_abs_error\":%.17g,\"max_rel_error\":null,\"jit_excluded\":true,\"timing_region\":\"resident3batch_fixed33_Tantan_HMM_masking_kernel_completion\",\"internal_repeats\":1,\"iterations\":1,\"kernel_launches\":3,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"float64\",\"count\":%zu,\"byte_order\":\"little\"}}\n",trial,seconds,good?"true":"false",out.size(),error,path.c_str(),out.size());fflush(stdout);if(!good)return 4;}
// Additional genuine GPU posterior observer afterall5timings, uses originaldevicehelper.
for(auto w:works)w->seq.reset();std::vector<double>trace;prefix(trace,mat,table,works);int off=0;double maximum=0;bool good=true;for(auto w:works){Buffer<float>prob(std::vector<float>(w->n*33,0),-999);Buffer<int>err(std::vector<int>(w->n,0),-12345);observe_posterior<<<(w->n+128)/128,128>>>(w->seq.ptr,mat.ptr,prob.ptr,err.ptr,w->n);C(cudaGetLastError());C(cudaDeviceSynchronize());std::vector<float>hp(w->n*33);std::vector<int>he(w->n);C(cudaMemcpy(hp.data(),prob.ptr,hp.size()*4,cudaMemcpyDeviceToHost));C(cudaMemcpy(he.data(),err.ptr,he.size()*4,cudaMemcpyDeviceToHost));for(float v:hp){double e=std::abs(v-posterior[off]);maximum=std::max(maximum,e);good=good&&std::isfinite(v)&&e<=3e-7+3e-7*std::abs(posterior[off]);off++;}for(int v:he)good=good&&v==0;prob.append(trace);err.append(trace);}std::string path=std::string(argv[3])+"/actual_posterior_"+std::to_string(getpid())+".bin";std::ofstream f(path,std::ios::binary);f.write((char*)trace.data(),trace.size()*8);f.close();printf("STUDY_AUXILIARY actual_untimed_original_helper_posterior correct=%s checked_posterior_values=%d total_artifact_values=%zu max_abs_error=%.17g path=%s\n",good?"true":"false",off,trace.size(),maximum,path.c_str());for(auto w:works)delete w;return good?0:5;}
